/*
 * game-state · 游戏状态与规则
 * 冻结契约：docs/contracts/snake-game-architecture-v1.md §2.1 / §3
 * 属主：game-core    写入根：src/game-state.js
 *
 * 职责边界：
 * - 维护 20×20 网格、蛇身与食物、方向缓冲、移动推进、撞墙/自撞判定、
 *   吃食物增长、速度档位与状态机（ready/playing/paused/over）。
 * - 规则层是唯一裁判：反向过滤、碰撞、增长只在此裁决。
 * - 不写 localStorage，不直接给当前分加分：加分唯一入口为 SnakeGame.score.onFood。
 *   tick 在 eat 时仅返回 scoreDelta（10），由装配层调用 score.onFood 落分。
 * - 模块间仅经 window.SnakeGame 命名空间交互，本模块无外部依赖。
 */
(function (global) {
  'use strict';

  var namespace = global.SnakeGame = global.SnakeGame || {};

  var DEFAULTS = {
    gridSize: 20,
    initialLength: 3,
    initialSpeedCps: 7
  };

  var MAX_SPEED_CPS = 12;      // 速度上限（格/秒）
  var SPEED_STEP_FOODS = 5;    // 每吃 5 个食物提速一档
  var SCORE_PER_FOOD = 10;     // 每个食物分值（由 score 模块落分，此处仅回传）

  var DIRECTIONS = {
    up: { x: 0, y: -1 },
    down: { x: 0, y: 1 },
    left: { x: -1, y: 0 },
    right: { x: 1, y: 0 }
  };

  var OPPOSITE = { up: 'down', down: 'up', left: 'right', right: 'left' };

  /*
   * 每局的初始参数保存在 WeakMap 中，不写入 game 对象，
   * 保证 game 数据形状严格等于契约字段（restart 也据此复位速度/网格）。
   */
  var configStore = createConfigStore();

  function createConfigStore() {
    if (typeof WeakMap === 'function') {
      var map = new WeakMap();
      return {
        get: function (key) {
          return key && typeof key === 'object' ? map.get(key) : undefined;
        },
        set: function (key, value) {
          if (key && typeof key === 'object') { map.set(key, value); }
        }
      };
    }
    var keys = [];
    var values = [];
    return {
      get: function (key) {
        var i = keys.indexOf(key);
        return i >= 0 ? values[i] : undefined;
      },
      set: function (key, value) {
        var i = keys.indexOf(key);
        if (i >= 0) { values[i] = value; }
        else { keys.push(key); values.push(value); }
      }
    };
  }

  function hasDirection(dir) {
    return typeof dir === 'string' && Object.prototype.hasOwnProperty.call(DIRECTIONS, dir);
  }

  function toInt(value, fallback) {
    var n = Number(value);
    if (!isFinite(n)) { return fallback; }
    return Math.floor(n);
  }

  function clampInt(value, min, max) {
    if (value < min) { return min; }
    if (value > max) { return max; }
    return value;
  }

  function resolveConfig(opts) {
    var source = (opts && typeof opts === 'object') ? opts : {};
    var gridSize = clampInt(toInt(source.gridSize, DEFAULTS.gridSize), 2, Number.MAX_SAFE_INTEGER || 9007199254740991);
    var initialLength = clampInt(toInt(source.initialLength, DEFAULTS.initialLength), 1, gridSize);
    var speed = Number(source.initialSpeedCps);
    if (!isFinite(speed) || speed <= 0) { speed = DEFAULTS.initialSpeedCps; }
    return {
      gridSize: gridSize,
      initialLength: initialLength,
      initialSpeedCps: speed
    };
  }

  function pickFoodCell(game) {
    var occupied = {};
    var i;
    for (i = 0; i < game.snake.length; i++) {
      occupied[game.snake[i].y * game.gridSize + game.snake[i].x] = true;
    }
    var free = [];
    for (var y = 0; y < game.gridSize; y++) {
      for (var x = 0; x < game.gridSize; x++) {
        if (!occupied[y * game.gridSize + x]) { free.push({ x: x, y: y }); }
      }
    }
    if (free.length === 0) { return null; }
    var index = Math.floor(Math.random() * free.length);
    if (index < 0) { index = 0; }
    if (index >= free.length) { index = free.length - 1; }
    return free[index];
  }

  function computeSpeed(game) {
    var config = configStore.get(game);
    var base = (config && isFinite(config.initialSpeedCps)) ? config.initialSpeedCps : DEFAULTS.initialSpeedCps;
    var speed = base + Math.floor(game.foodsEaten / SPEED_STEP_FOODS);
    return speed > MAX_SPEED_CPS ? MAX_SPEED_CPS : speed;
  }

  function result(event, scoreDelta, speedCps) {
    return { event: event, scoreDelta: scoreDelta, speedCps: speedCps };
  }

  /*
   * 构造新局：默认 20×20、蛇长 3、7 格/秒；蛇头为 snake[0]，
   * 初始朝右并横卧在网格中部，食物落在任一空格。
   */
  function createGame(opts) {
    var config = resolveConfig(opts);
    var game = {
      gridSize: config.gridSize,
      snake: [],
      direction: 'right',
      pendingDirection: null,
      food: null,
      score: 0,
      foodsEaten: 0,
      speedCps: config.initialSpeedCps,
      status: 'ready'
    };

    var startX = Math.max(config.initialLength - 1, Math.floor(game.gridSize / 2));
    var startY = Math.floor(game.gridSize / 2);
    for (var i = 0; i < config.initialLength; i++) {
      game.snake.push({ x: startX - i, y: startY });
    }

    game.food = pickFoodCell(game);
    if (!game.food) {
      // 网格容不下蛇以外的空格：按盘面填满处理，直接结束。
      game.status = 'over';
    }

    configStore.set(game, config);
    return game;
  }

  /* ready|paused → playing（暂停中开始即恢复）。 */
  function start(game) {
    if (!game) { return; }
    if (game.status === 'ready' || game.status === 'paused') {
      game.status = 'playing';
    }
  }

  /*
   * 方向输入：非法方向或直接反向返回 false 并忽略；
   * 否则写入单槽方向缓冲（pendingDirection）并返回 true。
   * 反向以“当前实际方向”为基准，避免缓冲覆盖后在同一节拍形成 180° 反转。
   */
  function changeDirection(game, dir) {
    if (!game || !hasDirection(dir)) { return false; }
    if (hasDirection(game.direction) && OPPOSITE[dir] === game.direction) { return false; }
    game.pendingDirection = dir;
    return true;
  }

  /*
   * 推进一个节拍：
   * - 非 playing 返回 noop，不改变状态；
   * - 应用方向缓冲 → 计算新蛇头 → 撞墙/自撞判定 → 吃食物增长或移动尾部；
   * - 撞墙/自撞立即置 status='over'；
   * - eat 时增长 +1、foodsEaten +1、按公式更新速度，返回 scoreDelta=10。
   */
  function tick(game) {
    if (!game || !game.snake || game.snake.length === 0) {
      return result('noop', 0, DEFAULTS.initialSpeedCps);
    }
    if (game.status !== 'playing') {
      return result('noop', 0, game.speedCps);
    }

    if (hasDirection(game.pendingDirection)) {
      if (game.pendingDirection !== game.direction && OPPOSITE[game.pendingDirection] !== game.direction) {
        game.direction = game.pendingDirection;
      }
      game.pendingDirection = null;
    }

    var step = DIRECTIONS[game.direction] || DIRECTIONS.right;
    var head = game.snake[0];
    var nextHead = { x: head.x + step.x, y: head.y + step.y };
    var size = game.gridSize;

    if (nextHead.x < 0 || nextHead.y < 0 || nextHead.x >= size || nextHead.y >= size) {
      game.status = 'over';
      game.pendingDirection = null;
      return result('wall', 0, game.speedCps);
    }

    var eating = !!game.food && nextHead.x === game.food.x && nextHead.y === game.food.y;

    // 不咬尾时（本步不吃食物）尾部格即将移走，自撞判定排除尾格。
    var checkLength = eating ? game.snake.length : game.snake.length - 1;
    for (var i = 0; i < checkLength; i++) {
      var segment = game.snake[i];
      if (segment.x === nextHead.x && segment.y === nextHead.y) {
        game.status = 'over';
        game.pendingDirection = null;
        return result('self', 0, game.speedCps);
      }
    }

    game.snake.unshift(nextHead);

    if (!eating) {
      game.snake.pop();
      return result('move', 0, game.speedCps);
    }

    game.foodsEaten += 1;
    game.speedCps = computeSpeed(game);

    var nextFood = pickFoodCell(game);
    if (nextFood) {
      game.food = nextFood;
    } else {
      // 盘面填满：无空格生成食物，按结束处理（本步仍计作 eat）。
      game.status = 'over';
    }

    return result('eat', SCORE_PER_FOOD, game.speedCps);
  }

  /* 返回重置后的新局：当前分/蛇身/速度复位，最高分由 score 模块独立保留。 */
  function restart(game) {
    var config = configStore.get(game);
    if (config) {
      return createGame({
        gridSize: config.gridSize,
        initialLength: config.initialLength,
        initialSpeedCps: config.initialSpeedCps
      });
    }
    var fallbackGrid = (game && isFinite(game.gridSize)) ? game.gridSize : DEFAULTS.gridSize;
    var fallbackLength = (game && game.snake && game.snake.length) ? game.snake.length : DEFAULTS.initialLength;
    return createGame({
      gridSize: fallbackGrid,
      initialLength: fallbackLength,
      initialSpeedCps: DEFAULTS.initialSpeedCps
    });
  }

  /* playing → paused */
  function pause(game) {
    if (game && game.status === 'playing') { game.status = 'paused'; }
  }

  /* paused → playing */
  function resume(game) {
    if (game && game.status === 'paused') { game.status = 'playing'; }
  }

  namespace.state = {
    createGame: createGame,
    start: start,
    changeDirection: changeDirection,
    tick: tick,
    restart: restart,
    pause: pause,
    resume: resume
  };
})(typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this));

