Now dispatched game-loop. Same gate situation likely. Let me attempt write to src/game-loop.js. First design implementation per §2.3.

createLoop({tick, draw, now?}) → loop with start/stop/pause/resume.
- rAF driven; accumulator step = 1000 / speedCps. But wait: speedCps comes from game state, not injected into createLoop. How does loop know speed? Contract: "累加器按 1000 / speedCps 计算步长". createLoop only receives tick, draw, now. Hmm. Perhaps the loop reads speed from tick()'s return ({speedCps})? tick returns {event, scoreDelta, speedCps}. So loop can call tick(), get speedCps, and use that for next step interval. That's a natural design: initial speedCps default 7 until first tick returns. But "暂停时不调用 tick"—fine.

Alternatively createLoop could accept speedCps option. Frozen interface only {tick, draw, now?}. So derive from tick() return. Use `stepMs = 1000 / speedCps`, speedCps from last tick result (default 7 / DEFAULT_SPEED_CPS = 7). This matches §3.7 speed from next tick.

Design:

```js
(function (global) {
  'use strict';
  var namespace = global.SnakeGame = global.SnakeGame || {};

  var DEFAULT_SPEED_CPS = 7;
  var MAX_CATCH_UP_STEPS = 5;

  function createLoop(options) {
    var opts = options || {};
    var tickFn = typeof opts.tick === 'function' ? opts.tick : function () {};
    var drawFn = typeof opts.draw === 'function' ? opts.draw : function () {};
    var nowFn = typeof opts.now === 'function' ? opts.now : defaultNow;

    var running = false;
    var paused = false;
    var rafId = null;
    var lastTime = 0;
    var accumulator = 0;
    var speedCps = DEFAULT_SPEED_CPS;
    var requestFrame = ...; cancelFrame...

    function defaultNow() {
      if (typeof performance !== 'undefined' && typeof performance.now === 'function') return performance.now();
      return Date.now ? Date.now() : 0;
    }

    function frame() {
      rafId = null;
      if (!running) return;
      var time = Number(nowFn());
      if (!isFinite(time)) time = lastTime;
      var delta = time - lastTime;
      lastTime = time;
      if (delta < 0) delta = 0;

      if (!paused) {
