(function (global) {
  'use strict';

  var namespace = global.SnakeGame = global.SnakeGame || {};

  var DEFAULT_SPEED_CPS = 7;     // 契约默认初始速度
  var MAX_STEPS_PER_FRAME = 5;   // 单帧追赶上限
  var FALLBACK_FRAME_MS = 16;    // 无 rAF 时的降级帧间隔

  function noop() {}

  function defaultNow() {
    if (typeof performance !== 'undefined' && performance && typeof performance.now === 'function') {
      return performance.now();
    }
    return Date.now();
  }

  function createLoop(options) {
    var opts = (options && typeof options === 'object') ? options : {};
    var tickFn = (typeof opts.tick === 'function') ? opts.tick : noop;
    var drawFn = (typeof opts.draw === 'function') ? opts.draw : noop;
    var nowFn = (typeof opts.now === 'function') ? opts.now : defaultNow;

    var running = false;
    var paused = false;
    var frameHandle = null;
    var scheduled = false;
    var lastTime = 0;
    var accumulator = 0;
    var speedCps = DEFAULT_SPEED_CPS;

    function readNow() {
      var t = Number(nowFn());
      return isFinite(t) ? t : 0;
    }

