(function (global) {
  'use strict';

  var namespace = global.SnakeGame = global.SnakeGame || {};

  var STORAGE_KEY = 'snake-game.highScore.v1';

  // DOM 兼容候选：入口页可按任一约定提供元素，减少装配期耦合。
  var IDS = {
    canvas: ['game-canvas', 'gameCanvas', 'snake-canvas', 'snakeCanvas', 'canvas'],
    scoreEl: ['score', 'current-score', 'currentScore', 'score-value', 'scoreValue'],
    highScoreEl: ['high-score', 'highScore', 'best-score', 'bestScore', 'highScoreValue'],
    statusEl: ['status', 'status-text', 'statusText', 'game-status', 'gameStatus', 'message'],
    restartButton: ['restart', 'restart-button', 'restartButton', 'btn-restart', 'btnRestart', 'restartBtn']
  };

  var initialized = false;

  function getDocument() {
    return global.document || null;
  }

  function byId(doc, ids) {
    if (!doc || typeof doc.getElementById !== 'function') { return null; }
    for (var i = 0; i < ids.length; i++) {
      var el = doc.getElementById(ids[i]);
      if (el) { return el; }
    }
    return null;
  }

  function resolveElements(doc) {
    return {
      canvas: byId(doc, IDS.canvas),
      scoreEl: byId(doc, IDS.scoreEl),
      highScoreEl: byId(doc, IDS.highScoreEl),
      statusEl: byId(doc, IDS.statusEl),
      restartButton: byId(doc, IDS.restartButton)
    };
  }

  function oneLine(message) {
    return String(message == null ? '' : message).replace(/[\r\n]+/g, ' ').slice(0, 160);
  }

  function writeStatus(doc, text) {
    try {
      var el = byId(doc, IDS.statusEl);
      if (el) { el.textContent = text; }
    } catch (e) { /* 状态区不可写时静默，避免二次异常 */ }
  }

  function reportStartupError(err) {
    var detail = (err && err.message) ? oneLine(err.message) : '';
    writeStatus(getDocument(), detail ? ('游戏启动失败：' + detail) : '游戏启动失败，请刷新页面重试。');
  }

  function boot() {
    var doc = getDocument();
    if (!doc) { return; }

    var api = namespace;
    if (!api.state || !api.score || !api.loop || !api.input || !api.render) {
      throw new Error('游戏模块未就绪');
    }

    var elements = resolveElements(doc);
    if (!elements.canvas) {
      throw new Error('未找到游戏画布元素');
    }

    var store = api.score.createScoreStore({ storageKey: STORAGE_KEY });
    var game = api.state.createGame();
    var renderer = api.render.createRenderer({
      canvas: elements.canvas,
      scoreEl: elements.scoreEl,
      highScoreEl: elements.highScoreEl,
      statusEl: elements.statusEl
    });

    function getHighScore() {
      var value = 0;
      try { value = api.score.getHighScore(store); } catch (e) { value = 0; }
      if (typeof value !== 'number' || !isFinite(value) || value < 0) { value = 0; }
      return Math.floor(value);
    }

    function draw() {
      try { renderer.draw(game, getHighScore()); } catch (e) { /* 渲染失败不阻断流程 */ }
    }

    function setStatus(status, payload) {
      try { renderer.setStatus(status, payload); } catch (e) { setStatusFallback(status); }
    }

    function setStatusFallback(status) {
      // renderer 不可用时退化为直接写状态区，保证提示可见。
      var text = '';
      if (status === 'ready') { text = '按方向键 / WASD / 空格开始'; }
      else if (status === 'paused') { text = '已暂停（P 继续）'; }
      else if (status === 'over') { text = '本局结束（R 或「重开」再来一局）'; }
      if (text) { writeStatus(doc, text); }
    }

    function guard(fn, handlerName) {
      return function () {
        try {
          return fn.apply(null, arguments);
        } catch (err) {
          reportRuntimeError(handlerName, err);
          return undefined;
        }
      };
    }

    function reportRuntimeError(handlerName, err) {
      var detail = (err && err.message) ? oneLine(err.message) : '';
      var text = '运行出错' + (detail ? ('：' + detail) : '') + '（按 R 重开）';
      writeStatus(doc, text);
    }

    function startGame() {
      if (game.status === 'ready' || game.status === 'paused') {
        api.state.start(game);
        loop.start();
        setStatus('playing');
        draw();
      }
    }

    function handleDirection(dir) {
      if (game.status === 'ready') { startGame(); }
      api.state.changeDirection(game, dir);
    }

    function togglePause() {
      if (game.status === 'playing') {
        api.state.pause(game);
        loop.pause();
        setStatus('paused');
        draw();
      } else if (game.status === 'paused') {
        api.state.resume(game);
        loop.resume();
        setStatus('playing');
        draw();
      }
    }

    function finishGame() {
      try { api.score.onGameOver(game, store); } catch (e) { /* 持久化失败静默 */ }
      var high = getHighScore();
      loop.stop();
      setStatus('over', { score: game.score, highScore: high });
      draw();
    }

    function handleTick() {
      var outcome = api.state.tick(game);
      var event = outcome && outcome.event;

      if (event === 'eat') {
        try { api.score.onFood(game, store); } catch (e) { reportRuntimeError('score.onFood', e); }
        draw();
      } else if (event === 'wall' || event === 'self') {
        finishGame();
      }

      return outcome;
    }

    function restartGame() {
      loop.stop();
      game = api.state.restart(game);
      try { api.score.resetCurrent(game); } catch (e) { /* 当前分已随新局清零 */ }
      startGame();
      draw();
    }

    var loop = api.loop.createLoop({
      tick: function () {
        try {
          return handleTick();
        } catch (err) {
          // 规则层异常：转为 noop，交给状态区提示，避免未捕获异常。
          reportRuntimeError('state.tick', err);
          return { event: 'noop', scoreDelta: 0, speedCps: game.speedCps };
        }
      },
      draw: draw
    });

    api.input.attach({
      onDirection: guard(handleDirection, 'input.onDirection'),
      onPauseToggle: guard(togglePause, 'input.onPauseToggle'),
      onRestart: guard(restartGame, 'input.onRestart'),
      onStart: guard(startGame, 'input.onStart')
    });

    if (elements.restartButton && typeof elements.restartButton.addEventListener === 'function') {
      elements.restartButton.addEventListener('click', guard(function (event) {
        if (event && typeof event.preventDefault === 'function') { event.preventDefault(); }
        restartGame();
      }, 'restartButton.onclick'));
    }

    setStatus('ready');
    draw();
  }

  function init() {
    if (initialized) { return; }
    initialized = true;
    try {
      boot();
    } catch (err) {
      reportStartupError(err);
    }
  }

  namespace.app = {
    init: init
  };

  // 若入口页未显式调用 init，则在 DOM 就绪后自动启动（init 幂等，显式调用优先）。
  var doc = getDocument();
  if (doc) {
    if (doc.readyState === 'loading') {
      doc.addEventListener('DOMContentLoaded', init);
    } else {
      init();
    }
  }
})(typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this));

